  fanout?: (boolean | {
    /** descriptor field to group by, e.g. "os" or "soc" */
    distinct: string;
  });
  targets?: {
    pool?: string;
    /** pin this job to exactly one device (a device-executor agent, or a device a host executor drives); the way to name a reserved device */
    device_id?: string;
    /** descriptor expression, e.g. "ram_mb >= 4000 && os ~ 'android'" — fields: model, soc, ram_mb, os, app_ver, device_id, pools; a reserved device is matched only by a job carrying its reservation whose expression pins its id; ops == != < <= > >= ~(regex) && || ! ( ) */
    match?: string;
    /** host jobs: hold collector device locks on all targets while running, starving device-executor agents until release */
    exclusive?: boolean;
    /** which host executor should claim this — a statement about which machine can reach the toolchain or the device, which no descriptor field can express */
    executor?: string;
    /** web-test only: what to point the browser at; no device is involved and none is locked */
    url?: string;
    /** host jobs: narrow selection to real hardware or simulators — a property of how a device is attached, which no descriptor field expresses honestly */
    device_kind?: "device" | "simulator";
  };
  /** Device-state preconditions. require_charging and min_battery_pct are enforced by the runner app at claim time, against live state: it refuses the job with a failed result. The rest are enforced by the collector before the claim, against the device's last beacon, so the job stays queued and is offered again later rather than burning an attempt. The split is deliberate — a laptop that is merely busy has not failed at anything. */
